"""Static offline production dashboard. No external runtime or network dependencies."""
from pathlib import Path
import json
ROOT=Path(__file__).resolve().parent
def read(name):return json.loads((ROOT/name).read_text(encoding='utf-8'))
payload=json.dumps({'props':read('prop_catalog.json'),'materials':read('materials.json'),'rooms':read('room_dressing.json'),'art':read('image_jobs.json'),'trims':read('trim_metadata.json')},ensure_ascii=False).replace('</',r'<\/')
template=r'''<!doctype html><html lang="en"><head><meta charset="utf-8"><meta name="viewport" content="width=device-width,initial-scale=1"><title>Warrens C / dressing production pack</title><style>
:root{color-scheme:dark;--ink:#eee1c0;--muted:#bcb49d;--bg:#1e251f;--panel:#2a3229;--line:#596047;--gold:#d3b46f}*{box-sizing:border-box}body{margin:0;background:var(--bg);color:var(--ink);font:16px/1.5 system-ui}header,main{max-width:1560px;margin:auto;padding:28px}h1,h2,h3{font-family:Georgia,serif;line-height:1.15}h1{font-size:44px;margin:10px 0}h2{font-size:32px}p{max-width:1100px}a{color:#e1c887}nav,.toolbar,.downloads{display:flex;gap:10px;flex-wrap:wrap;align-items:center}button,input,select{font:inherit;color:var(--ink);background:#30392e;border:1px solid var(--line);border-radius:5px;padding:9px 13px}button{cursor:pointer}button.on{background:var(--gold);color:#20271e}input{flex:1;min-width:240px}.small{font-size:14px;color:var(--muted)}.hero{width:100%;max-height:620px;object-fit:contain;background:#1a211b}.grid{display:grid;grid-template-columns:repeat(auto-fit,minmax(330px,1fr));gap:20px}.card{background:var(--panel);border:1px solid var(--line);border-radius:7px;padding:18px}.card img{width:100%;aspect-ratio:3/2;object-fit:contain;background:#30382e}.material img{aspect-ratio:1}.material h3,.card h3{margin:12px 0}.tag{font-size:12px;letter-spacing:.1em;text-transform:uppercase;color:var(--gold)}.badge{display:inline-block;border:1px solid #788163;padding:2px 8px;border-radius:4px;font-size:13px}.source{border-left:3px solid var(--gold);padding:15px 20px;background:var(--panel)}section{display:none}section.active{display:block}table{border-collapse:collapse;width:100%;font-size:14px}td,th{padding:12px;text-align:left;border-bottom:1px solid #4c5744;vertical-align:top}th{color:#dcc18a}summary{cursor:pointer;color:#e2c77e}textarea{width:100%;height:160px;background:#1f261f;color:var(--ink);font:14px/1.5 monospace;padding:12px;border:1px solid var(--line)}.scroller{overflow:auto}.links{display:flex;gap:12px;flex-wrap:wrap}.room{margin:24px 0}.room p{max-width:none}.room img{width:100%;max-height:420px;object-fit:contain}.toplinks{margin:20px 0}.count{margin:12px 0;color:#cbbd98}#layout{width:100%;max-height:900px;background:#20271f}footer{margin:40px 0;color:var(--muted)}@media(max-width:700px){header,main{padding:16px}h1{font-size:32px}.grid{grid-template-columns:1fr}}
</style></head><body><header><div class="tag">MISE EN MONSTRE / WARRENS C / DRESSING R01</div><h1>Two towers, one coherent art kit</h1><p>19 material families · 126 prop briefs · 11 source tiles · 12 modeling sheets · 6 transparent painted graphics. Actual texture inputs and a packed Blender material library, with proposals clearly separated from current layout measurements.</p><div class="downloads toplinks"><a href="blender/WarrensC_MaterialLibrary.blend">Blender material library</a><a href="WarrensC-Dressing-Pack-r01.zip">Full pack ZIP</a><a href="prop_catalog.csv">Prop tracker CSV</a><a href="prop_catalog.json">Prop data JSON</a><a href="ASSEMBLY_RECIPES.md">Source assembly recipes</a><a href="README.md">Read me</a></div><div class="source">Start with the <a href="BLENDER_AUTHORING.md">24-entry first batch</a>, then <a href="ROOM_DRESSING.md">tile-specific dressing</a>. Current JSON owns ports, dimensions and puzzle relationships; paintings supply visual direction. P7 curing stays in Salt Mill. The key is on the accessible +2.5m loft, separate from the high bell. No live-map or gameplay changes.</div><nav style="margin-top:24px"><button data-page="overview" class="on">Overview</button><button data-page="materials">Materials & maps</button><button data-page="props">Prop catalog</button><button data-page="rooms">Tile dressing</button><button data-page="art">Modeling & painted art</button></nav></header><main>
<section id="overview" class="active"><h2>Build the silhouettes first</h2><img class="hero" src="qa/NEUTRAL_MATERIALS.png" alt="Rendered neutral Blender material swatches"><div class="grid" style="margin-top:22px"><article class="card"><h3>Material contract</h3><p>95 surface maps plus palette, trim, alpha art and FX inputs. Neutral albedo; aligned technical maps; both normal conventions.</p><a href="MATERIAL_GUIDE.md">Channels, UVs and import notes</a></article><article class="card"><h3>Modeling contract</h3><p>Dimensions, pivots, separate moving parts, UV scheme, collision policy, material IDs and a ready-to-copy prompt for every entry.</p><a href="BLENDER_AUTHORING.md">Blender handoff</a></article><article class="card"><h3>Layout contract</h3><p>All 24 room records, all 11 current tile boundaries and the ten authored landmark/clue views are covered.</p><a href="SOURCE.json">Source authority and differences</a></article></div><h2>Readability under a lamp</h2><img class="hero" src="qa/LANTERN_MATERIALS.png" alt="Rendered warm/cool material study"><p class="small">Blender studio study, not Unreal game-camera lighting acceptance. No production prop meshes or dressed map are supplied by the swatch scene.</p><h2>Current source footprints</h2><img id="layout" src="SOURCE_FOOTPRINTS.svg" alt="Actual source tile and room footprints with protected view rays"><p class="small">Stacked floors overlap in this 2D diagram. It does not add any route or replace the authored level layout.</p></section>
<section id="materials"><h2>Quiet surfaces, reusable maps</h2><p>BaseColor is sRGB. ORM, height and normals are linear. Use NormalGL in Blender and NormalDX in Unreal. Full channel/UV notes: <a href="MATERIAL_GUIDE.md">material guide</a>.</p><div class="grid" id="materialGrid"></div><h2>Palette, trim and exact glyphs</h2><img class="hero" src="qa/ATLASES_AND_ART.png" alt="Blender render of atlases and art"><div class="links"><a href="textures/atlases/AT01_Palette_BaseColor.png">Palette</a><a href="palette.json">Swatch UV centers</a><a href="trim_metadata.json">Trim bands / gutters</a><a href="decal_metadata.json">Glyph and navigation UVs</a><a href="textures/atlases/AT04_GlyphAndNavigation_Alpha.png">Alpha atlas</a><a href="fx_metadata.json">Water and FX channels</a></div><div id="trimGrid" class="grid" style="margin-top:20px"></div><h2>2×2 repeat checks</h2><img class="hero" src="qa/TILING_2X2.jpg" alt="Four repeated texture checks"></section>
<section id="props"><h2>126 modular art entries</h2><p>Generate each shared asset once, then instance it across its listed tiles. P0 is the core set; P1 supplies room identity; P2 is optional. Existing actors remain gameplay/collision authority. <a href="BLENDER_AUTHORING.md">Start with the 24-entry batch</a>.</p><div class="toolbar"><input id="search" placeholder="Search ID, prop, room or material" aria-label="Search props"><select id="priority" aria-label="Priority"><option value="">All priorities</option><option>P0</option><option>P1</option><option>P2</option></select><select id="tile" aria-label="Tile"></select><select id="category" aria-label="Category"></select><button id="export">Export filtered briefs</button></div><div class="count" id="count"></div><div class="scroller"><table><thead><tr><th>Asset</th><th>Priority / role</th><th>Dimensions / basis</th><th>Materials / tiles</th><th>Blender request</th></tr></thead><tbody id="propRows"></tbody></table></div></section>
<section id="rooms"><h2>Dress the level without changing its routes</h2><p>All densities are proposed, not measured actor counts. Keep current widths, rail gaps, drop landings, low passages, controls and source sightlines clear. <a href="ROOM_DRESSING.md">Complete placement and acceptance guide</a>.</p><div id="roomList"></div></section>
<section id="art"><h2>Modeling sheets and decorative graphics</h2><p>Click for native full resolution. Written catalog dimensions win over AI dimension labels. Decorative emblems are separate from the six canonical lock glyphs. Native transparent art is 1254px and may be baked onto a power-of-two prop atlas during production.</p><div class="grid" id="artGrid"></div></section>
<footer>Offline art production handoff. Technical maps are code-native; painted graphics/model sheets use built-in image generation. No Unreal import, dressed-level acceptance, gameplay implementation, commit or push is implied. Verification: <a href="VERIFICATION.json">pack report</a>.</footer></main><script>
const DATA=__DATA__;let filtered=DATA.props;const $=s=>document.querySelector(s);const esc=v=>String(v).replace(/[&<>"']/g,c=>({'&':'&amp;','<':'&lt;','>':'&gt;','"':'&quot;',"'":'&#39;'}[c]));
function draws(){const term=$('#search').value.toLowerCase(),p=$('#priority').value,t=$('#tile').value,c=$('#category').value;filtered=DATA.props.filter(a=>(!p||a.priority===p)&&(!t||a.tiles.includes(t))&&(!c||a.category===c)&&JSON.stringify(a).toLowerCase().includes(term));$('#count').textContent=filtered.length+' entries shown · '+filtered.reduce((n,a)=>n+a.variants,0)+' proposed variants (not completed models)';$('#propRows').innerHTML=filtered.map(a=>`<tr><td><b>${a.id}</b><br>${esc(a.name)}<p class="small">${esc(a.asset_name)}<br>${a.variants} variant(s)</p></td><td><span class="badge">${a.priority}</span><p>${esc(a.category)}</p><p class="small">${esc(a.status)}</p></td><td>${Object.values(a.dimensions_cm).join(' × ')} cm<p class="small">${esc(a.dimension_basis)}</p></td><td>${a.materials.join(', ')}<p class="small">${a.tiles.join(', ')}</p></td><td><details><summary>Brief, pivot and collision</summary><p>${esc(a.notes)}</p><p><b>Pivot:</b> ${esc(a.pivot)}</p><p><b>Collision:</b> ${esc(a.collision)}</p><p><b>LOD0 target:</b> ${a.lod0_triangles_target_range.join('–')} triangles (proposal)</p><textarea readonly aria-label="Blender brief for ${a.id}">${esc(a.blender_generation_brief)}</textarea><a href="briefs/${a.id}_${a.name}.md">Individual brief file</a></details></td></tr>`).join('')}
$('#tile').innerHTML='<option value="">All tiles</option>'+DATA.rooms.map(r=>`<option>${r.id}</option>`).join('');$('#category').innerHTML='<option value="">All categories</option>'+[...new Set(DATA.props.map(p=>p.category))].map(c=>`<option>${c}</option>`).join('');['search','priority','tile','category'].forEach(id=>$('#'+id).addEventListener(id==='search'?'input':'change',draws));
document.querySelectorAll('[data-page]').forEach(b=>b.onclick=()=>{document.querySelectorAll('section').forEach(s=>s.classList.toggle('active',s.id===b.dataset.page));document.querySelectorAll('[data-page]').forEach(x=>x.classList.toggle('on',x===b))});
$('#materialGrid').innerHTML=DATA.materials.map(m=>`<article class="card material"><a href="${m.maps.BaseColor}"><img loading="lazy" src="${m.maps.BaseColor}" alt="${m.name} unlit base color"></a><div class="tag">${m.id} / ${m.family}</div><h3>${m.name}</h3><p class="small">${m.tile_metres.join(' × ')} m repeat · ${m.relief_mm} mm relief reference</p><div class="links">${Object.entries(m.maps).map(([k,v])=>`<a href="${v}">${k}</a>`).join('')}</div></article>`).join('');
$('#trimGrid').innerHTML=DATA.trims.map(t=>`<article class="card"><a href="${t.maps.BaseColor}"><img src="${t.maps.BaseColor}" alt="${t.name}"></a><h3>${t.id} ${t.name}</h3><p>Repeat U only; keep V inside a single guttered band.</p><div class="links">${Object.entries(t.maps).map(([k,v])=>`<a href="${v}">${k}</a>`).join('')}</div></article>`).join('');
$('#roomList').innerHTML=DATA.rooms.map(r=>`<article class="card room"><div class="tag">Source tile / ${r.id}</div><h3>${esc(r.identity)}</h3><p class="small">Rooms: ${r.rooms.join(', ')} · Concepts: ${r.concepts.join(', ')}</p><p><b>Hero:</b> ${r.hero.join(', ')}<br><b>Support:</b> ${r.support.join(', ')}<br><b>Materials:</b> ${r.materials.join(', ')}</p><p><b>Place:</b> ${esc(r.placement)}</p><p><b>Keep clear:</b> ${esc(r.avoid)}</p><p><b>Small story:</b> ${esc(r.story)}</p><p class="small">Protected named views: ${r.views.join(', ')||'See all intersecting source views and ports'}</p></article>`).join('');
$('#artGrid').innerHTML=DATA.art.map(a=>`<article class="card"><a href="${a.image}"><img loading="lazy" src="${a.image}" alt="${a.title}"></a><div class="tag">${a.id} / ${a.type}</div><h3>${a.title}</h3><p class="small">${esc(a.brief)}</p>${a.catalog_ids?'<p>Catalog: '+a.catalog_ids.join(', ')+'</p>':''}<div class="links"><a href="${a.image}">Full image</a><a href="prompts/${a.id}.txt">Generation prompt</a>${a.edit_prompt?`<a href="prompts/${a.id}_r02-edit.txt">Correction prompt</a>`:''}</div></article>`).join('');
$('#export').onclick=()=>{const blob=new Blob([JSON.stringify(filtered,null,2)],{type:'application/json'}),a=document.createElement('a');a.href=URL.createObjectURL(blob);a.download='WarrensC-filtered-Blender-briefs.json';a.click();setTimeout(()=>URL.revokeObjectURL(a.href),1000)};draws();
</script></body></html>'''
template=template.replace('126','150').replace('12 modeling sheets','38 modeling sheets · 11 district assembly sheets')
template=template.replace('<a href="prop_catalog.csv">','<a href="VISUAL_COVERAGE.md">Every prop → its sheets</a><a href="prop_catalog.csv">')
template=template.replace('<h1>Two towers, one coherent art kit</h1>','<h1>Two towers, one coherent art kit</h1><p class="source"><a href="sections/chain-crossing-sluice/PREVIEW.html"><b>Chain Crossing & Sluice: complete local kit</b></a> · 88 components · 23 model sheets · 4 assembly/player views</p>')
template=template.replace('<option value="painted">Painted graphics (6)</option>','<option value="painted">Painted graphics (6)</option><option value="section-sheet">Chain Crossing / Sluice (27)</option>')
template=template.replace('<h2>Build the silhouettes first</h2>','<h2>The whole-level art kit</h2><img class="hero" src="OVERVIEW.jpg" alt="Rocks, cave shell, water, bell and district assembly references"><p><a href="VISUAL_COVERAGE.md">149 new-model candidates with linked references</a> · I14 reuses the existing Red key. Filter the sheets below by asset, name or district.</p><h2>Build the silhouettes first</h2>')
template=template.replace('<div class="grid" id="artGrid">','<div class="toolbar"><input id="artSearch" placeholder="Search rocks, water, bells, asset ID or district" aria-label="Search art sheets"><select id="artKind" aria-label="Art sheet type"><option value="">All art</option><option value="model-sheet">Modeling sheets (38)</option><option value="dressing-sheet">District assemblies (11)</option><option value="painted">Painted graphics (6)</option></select></div><p class="count" id="artCount"></p><div class="grid" id="artGrid">')
template=template.replace('Individual brief file</a></details>','Individual brief file</a><p><b>Model references:</b> ${a.model_sheets.map(s=>`<a href="${s.image}">${s.id}</a>`).join(" · ")||"Reuse existing Red key"}</p></details>')
template=template.replace("$('#artGrid').innerHTML=DATA.art.map(a=>", "function drawArt(){const q=$('#artSearch').value.toLowerCase(),kind=$('#artKind').value;const items=DATA.art.filter(a=>(!kind||a.type===kind)&&JSON.stringify(a).toLowerCase().includes(q));$('#artCount').textContent=items.length+' art sheets shown';$('#artGrid').innerHTML=items.map(a=>")
template=template.replace('<h3>${a.title}</h3>','<h3>${a.title}</h3>${a.type===\'dressing-sheet\'?\'<p class="notice">Exploratory composition only. In-image IDs and arrangements are non-authoritative; use catalog links and MODEL/CS sheets. Not a placement plan.</p>\':\'\'}')
template=template.replace('<h2>Dress the level without changing its routes</h2>','<h2>Dress the level without changing its routes</h2><p class="source">District assembly images are composition studies with known label/layout drift. Use the written placement constraints and source JSON for actual dressing. The Chain Crossing dossier provides the detailed local component kit.</p>')
template=template.replace("$('#export').onclick=", "}\n['artSearch','artKind'].forEach(id=>$('#'+id).addEventListener(id==='artSearch'?'input':'change',drawArt));drawArt();\n$('#export').onclick=")
template=template.replace("${r.views.join(', ')||'See all intersecting source views and ports'}</p></article>","${r.views.join(', ')||'See all intersecting source views and ports'}</p><p><b>Environment kit:</b> ${r.environment_kit.join(', ')}</p>${DATA.art.filter(a=>a.type==='dressing-sheet'&&a.tiles.includes(r.id)).map(a=>`<a href=\"${a.image}\"><img loading=\"lazy\" src=\"${a.image}\" alt=\"${a.title}\"></a>`).join('')}</article>")
template=template.replace('<option value="painted">Painted graphics (6)</option>','<option value="painted">Painted graphics (6)</option><option value="section-sheet">Chain Crossing / Sluice (27)</option>')
(ROOT/'PREVIEW.html').write_text(template.replace('__DATA__',payload),encoding='utf-8')
print('Production dashboard built.')
